-- Generated by `yidam export --format warehouse` from this corpus's ontology. Regenerate rather than edit; an edited file is refused on the next export.
--
-- Feed `gcp-cai`: class `compute-instance` into `compute_instance`.
-- Cloud Asset Inventory export, per-asset-type tables, daily.
-- Mode: snapshot: rows of this origin that landing no longer holds are deleted.
-- Parameters, to substitute before running (nothing else here is a template):
--   ${landing_dataset}  The dataset CAI exports into.
--   ${project}  The GCP project holding the landing dataset.
-- Run with the contract's dataset as the job's default dataset, as 0001_init.sql is.

DECLARE loaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP();

CREATE TEMP TABLE _staged AS
SELECT
  CAST(name AS STRING) AS `id`,
  CAST('gcp' AS STRING) AS `provider`,
  CAST(resource.data.machineType AS STRING) AS `machine_type`,
  CAST(DATE(TIMESTAMP(resource.data.creationTimestamp)) AS DATE) AS `created`,
  CAST("day" AS STRING) AS `created_precision`
FROM `${project}.${landing_dataset}.cai_compute_googleapis_com_Instance`
WHERE (resource.data.status != 'TERMINATED');

SELECT ERROR(FORMAT("compute_instance: landing holds %T more than once (`id`)", `id`))
FROM _staged
GROUP BY `id`
HAVING COUNT(*) > 1
LIMIT 1;

SELECT ERROR(FORMAT("compute_instance.provider: %T is not a declared value", v))
FROM (SELECT DISTINCT `provider` AS v FROM _staged)
WHERE v IS NOT NULL AND v NOT IN (SELECT `value` FROM `vocab_compute_instance__provider`)
LIMIT 1;

SELECT ERROR(FORMAT("compute_instance.created_precision: %T is not a declared value", v))
FROM (SELECT DISTINCT `created_precision` AS v FROM _staged)
WHERE v IS NOT NULL AND v NOT IN ("year", "month", "day")
LIMIT 1;

MERGE `compute_instance` AS T
USING _staged AS S
ON T.`id` = S.`id` AND T.`_origin` = "gcp-cai"
WHEN MATCHED THEN
  UPDATE SET `provider` = S.`provider`, `machine_type` = S.`machine_type`, `created` = S.`created`, `created_precision` = S.`created_precision`, `_loaded_at` = loaded_at, `_source` = "gcp-cloud-asset-inventory"
WHEN NOT MATCHED THEN
  INSERT (`id`, `provider`, `machine_type`, `created`, `created_precision`, `_origin`, `_loaded_at`, `_source`)
  VALUES (S.`id`, S.`provider`, S.`machine_type`, S.`created`, S.`created_precision`, "gcp-cai", loaded_at, "gcp-cloud-asset-inventory")
WHEN NOT MATCHED BY SOURCE AND T.`_origin` = "gcp-cai" THEN
  DELETE;
